INSERT INTO `charge_settings` VALUES (33,'處置費','中度複雜性針灸-另開內服藥',NULL,NULL,NULL,NULL,'D05',327,'支付規範:\n                (1)須針灸二個(含)以上部位：頭頸部、軀幹部或四肢，任兩部位或以上。\n                (2)須合併以下任一輔助治療：拔罐治療、放血治療、刮痧治療、熱療(含紅外線治療)、艾灸治療、電療或眼部特殊針灸。\n                (3)治療時間合計十分鐘以上。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (34,'處置費','中度複雜性針灸',NULL,NULL,NULL,NULL,'D06',327,'支付規範:\n                (1)須針灸二個(含)以上部位：頭頸部、軀幹部或四肢，任兩部位或以上。\n                (2)須合併以下任一輔助治療：拔罐治療、放血治療、刮痧治療、熱療(含紅外線治療)、艾灸治療、電療或眼部特殊針灸。\n                (3)治療時間合計十分鐘以上。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (35,'處置費','高度複雜性針灸-另開內服藥',NULL,NULL,NULL,NULL,'D07',427,'支付規範:\n                (1)須針灸二個(含)以上部位：頭頸部、軀幹部或四肢，任兩部位或以上。\n                (2)須合併以下任一輔助治療：拔罐治療、放血治療、刮痧治療、熱療(含紅外線治療)、艾灸治療、電療或眼部特殊針灸。\n                (3)治療時間合計二十分鐘以上。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (36,'處置費','高度複雜性針灸',NULL,NULL,NULL,NULL,'D08',427,'支付規範:\n                (1)須針灸二個(含)以上部位：頭頸部、軀幹部或四肢，任兩部位或以上。\n                (2)須合併以下任一輔助治療：拔罐治療、放血治療、刮痧治療、熱療(含紅外線治療)、艾灸治療、電療或眼部特殊針灸。\n                (3)治療時間合計二十分鐘以上。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (37,'處置費','一般傷科-另開內服藥',NULL,NULL,NULL,NULL,'E01',227,'標準作業程序:\n                (1)四診八綱辨證(2)診斷(3)理筋手法\n            適應症:\n                (1)急慢性扭、挫、瘀傷: 踝扭傷、腰扭傷、頸部扭傷等。\n                (2)肌腱炎: 網球肘、棒球肩、腕部橈側腱鞘炎等。\n                      關節病變: 類風濕性關節炎、退化性關節炎、僵直性關節炎、痛風、冰凍肩(凝肩)等。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (38,'處置費','一般傷科',NULL,NULL,NULL,NULL,'E02',227,'標準作業程序:\n                (1)四診八綱辨證(2)診斷(3)理筋手法\n            適應症:\n                (1)急慢性扭、挫、瘀傷: 踝扭傷、腰扭傷、頸部扭傷等。\n                (2)肌腱炎: 網球肘、棒球肩、腕部橈側腱鞘炎等。\n                      關節病變: 類風濕性關節炎、退化性關節炎、僵直性關節炎、痛風、冰凍肩(凝肩)等。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (39,'處置費','中度複雜性傷科治療-療程第一次-另開內服藥',NULL,NULL,NULL,NULL,'E03',427,'支付規範:\n                (1)須合併以下任一輔助治療: 藥薰治療、拔罐治療、刮痧治療、電療、熱療(含紅外線治療)、膏布治療或夾板固定治療。\n                (2)治療時間合計十分鐘以上。(3)療程第二次-第六次以一般傷科處置(E01, E02)申報。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (40,'處置費','中度複雜性傷科治療-療程第一次',NULL,NULL,NULL,NULL,'E04',427,'支付規範:\n                (1)須合併以下任一輔助治療: 藥薰治療、拔罐治療、刮痧治療、電療、熱療(含紅外線治療)、膏布治療或夾板固定治療。\n                (2)治療時間合計十分鐘以上。(3)療程第二次-第六次以一般傷科處置(E01, E02)申報。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (41,'處置費','高度複雜性傷科治療-多部位損傷-起始次-另開內服藥',NULL,NULL,NULL,NULL,'E05',877,'通則:\n                1.起始次: 係指該病人受傷部位初次到醫療院所做之處理治療。脫臼整復、骨折之起始次處置，含再次復位、再次接骨。\n                2.後續治療處置以一般傷科治療處置(E01, E02)申報。\n                3.須合併以下任一輔助治療: 藥薰治療、拔罐治療、刮痧治療、電療、熱療(含紅外線治療)、膏布治療或夾板固定治療。\n                4.治療時間合計二十分鐘以上。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (42,'處置費','高度複雜性傷科治療-多部位損傷-起始次',NULL,NULL,NULL,NULL,'E06',877,'通則:\n                1.起始次: 係指該病人受傷部位初次到醫療院所做之處理治療。脫臼整復、骨折之起始次處置，含再次復位、再次接骨。\n                2.後續治療處置以一般傷科治療處置(E01, E02)申報。\n                3.須合併以下任一輔助治療: 藥薰治療、拔罐治療、刮痧治療、電療、熱療(含紅外線治療)、膏布治療或夾板固定治療。\n                4.治療時間合計二十分鐘以上。','2025-04-01 05:11:25');
