INSERT INTO `charge_settings` VALUES (85,'照護費','生理評估費',NULL,NULL,NULL,NULL,'P56007',1000,'1.癌症治療功能性評估：一般性量表 2.生活品質評估。前測(收案三日內)及後測(收案三個月內)量表皆完成，方可申請給付。限三個月申報一次，並於病歷詳細載明評估結果。','2025-04-01 05:11:25');
