INSERT INTO `charge_settings` VALUES (101,'照護費','疾病管理照護費',NULL,NULL,NULL,NULL,'P64011',500,'\n            1.中醫衛教、營養飲食指導、運動指導及檢查數據記載(雲端查詢)。\n            2.須檢附相關檢查數據：\n                CKD stage 2 病人後續每6個月須重新檢附於病歷；\n                CKD stage 3~4 病人後續每3個月須重新檢附 於病歷；\n                CKD stage 5 病人後續每個月須重新檢附於病歷。\n            3.限 60 天申報一次。','2025-04-01 05:11:25');
INSERT INTO `charge_settings` VALUES (102,'照護費','中醫慢性腎臟病治療功能性評估',NULL,NULL,NULL,NULL,'P64012',700,'\n            註 1：每一個案限每 6 個月申報一次費用(每次須同時完成各項所列之量表)\n            註 2：需有病人新收案或前一次功能性評估之量表及檢驗檢查，且已於 VPN 登錄者，使得申報本項。\n            註 3：申報 2 次加強照護費及 1 次疾病管理照護費後，始得申報 本項。','2025-04-01 05:11:25');
