INSERT INTO `charge_settings` VALUES (273,'處置費','整合醫療照護費加計',NULL,NULL,NULL,NULL,'A91',70,'註:\n1.慢性病或重大傷病病人,且為多重疾病者。\n2.診療時間合計十分鐘以上,並根據診斷結果至少提供一項中醫醫療衛教\n(如中醫飲食衛教、穴位經絡衛教、簡易中醫運動衛教或各類中藥使用衛\n教等),並於病歷記錄評估結果及所提供之中醫醫療衛教項目。','2025-04-01 05:12:08');
INSERT INTO `charge_settings` VALUES (274,'處置費','未滿七歲兒童傷科治療處置費加計',NULL,NULL,NULL,NULL,'E90',200,'註:\n1.須合併以下任一輔助治療:CH01 拔罐治療、CH02 刮痧治療、CH03 熱療\n(含紅外線治療)、CH04 電療、CH08 藥薰治療、CH09 膏布治療或 CH10\n夾板固定治療。\n2.治療時間合計十分鐘以上。','2025-04-01 05:12:08');
